// End-to-end test for the `otfw dev` loop over a **docs** project (@opentf/web-docs).
//
//   bun packages/web-cli/tests/e2e/dev-docs-hmr.mjs
//
// The docs sidebar is generated by a Rolldown plugin from the file tree — page
// frontmatter and `_meta.*` files — not from imports. So the chunk that holds it has
// dependencies no module crawl can see, and the plugin has to re-read a `_meta.js`
// that changed since the server started (a plain `import()` cannot: the runtime caches
// ESM by path). Both are dev-only failure modes that a build never hits, and both used
// to mean "edit a doc title, restart the server to see it".
//
// Needs the workspace otfwc debug build (OTFWC_BIN) and `@opentf/web-docs` resolvable
// from the repo. Exits 0 if every assertion holds, 1 otherwise.

import { mkdirSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = fileURLToPath(new URL(".", import.meta.url));
const ROOT = fileURLToPath(new URL("../../../../", import.meta.url));
const CLI = ROOT + "packages/web-cli/src/cli.js";
const OTFWC = process.env.OTFWC_BIN || ROOT + "target/debug/otfwc";
const APP = join(HERE, ".dev-docs-app");
const PORT_BASE = 43000;

let passed = 0;
const assert = (cond, label) => {
  if (!cond) throw new Error(`assertion failed: ${label}`);
  passed++;
  console.log(`  ✓ ${label}`);
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const SETTLE = 2000;

const write = (rel, source) => {
  const file = join(APP, rel);
  mkdirSync(join(file, ".."), { recursive: true });
  writeFileSync(file, source);
  return file;
};

function scaffold() {
  rmSync(APP, { recursive: true, force: true });
  write("package.json", JSON.stringify({ name: "otfw-dev-docs-app", private: true, type: "module" }) + "\n");
  write("index.html", `<!doctype html><html><head><title>Docs</title></head><body><div id="app"></div></body></html>\n`);
  write("otfw.config.js", `export default { docs: { title: "Fixture" } };\n`);
  // The sidebar tree, rendered as text — this is the chunk under test.
  write("app/layout.jsx", `import nav from "@opentf/web-docs/nav";\nexport default function Layout({ children }) { return <main><pre>{JSON.stringify(nav)}</pre>{children}</main>; }\n`);
  write("app/page.jsx", `export default function Home() { return <h1>Home</h1>; }\n`);
  write("app/docs/_meta.js", `export default { alpha: "Alpha" };\n`);
  write("app/docs/page.mdx", `---\ntitle: Docs\n---\n\nIndex.\n`);
  write("app/docs/alpha/page.mdx", `---\ntitle: Alpha Page\n---\n\nAlpha body.\n`);
}


// Point the fixture at the workspace packages, so the test exercises this checkout
// rather than whatever copy of @opentf/* the runtime's global cache happens to hold.
function linkWorkspace() {
  const dir = join(APP, "node_modules/@opentf");
  mkdirSync(dir, { recursive: true });
  for (const name of ["web", "web-docs"]) {
    const target = join(ROOT, "packages", name);
    const link = join(dir, name);
    rmSync(link, { recursive: true, force: true });
    symlinkSync(target, link, "dir");
  }
}

// Start the dev server on a free high port. Not the default 3000: a developer's own
// server (and the browser tab pointed at it) commonly owns that one, and it would
// answer these requests — or take the reloads meant for this test. A port we pick can
// still be taken, so a busy one is retried rather than failing the run.
async function startDevServer(attempts = 5) {
  for (let i = 0; i < attempts; i++) {
    const port = PORT_BASE + Math.floor(Math.random() * 2000);
    const proc = Bun.spawn(["bun", CLI, "dev", "--port", String(port)], {
      cwd: APP,
      env: { ...process.env, OTFWC_BIN: OTFWC },
      stdout: "pipe",
      stderr: "inherit",
    });
    const decoder = new TextDecoder();
    let buf = "";
    const deadline = Date.now() + 60000;
    let ready = false;
    for await (const chunk of proc.stdout) {
      buf += decoder.decode(chunk);
      if (buf.includes(`localhost:${port}`) && /ready in/.test(buf)) {
        ready = true;
        break;
      }
      if (Date.now() > deadline) break;
    }
    if (ready) {
      // Keep draining so the child never blocks on a full stdout pipe.
      (async () => {
        try {
          for await (const _ of proc.stdout);
        } catch {}
      })();
      return { proc, port };
    }
    proc.kill();
    if (i === attempts - 1) throw new Error(`dev server did not start on port ${port}:\n${buf}`);
  }
}

const routeUrl = (file) => `/__route/${Buffer.from(file).toString("base64url")}.js`;

async function main() {
  scaffold();
  linkWorkspace();

  const { proc, port } = await startDevServer();

  const BASE = `http://localhost:${port}`;
  const text = async (path) => (await fetch(BASE + path)).text();
  const layout = join(APP, "app/layout.jsx");
  const sidebar = () => text(routeUrl(layout));

  try {
    await text("/");
    await text("/bundle.js");
    assert((await sidebar()).includes("Alpha"), "the sidebar tree is generated into the layout chunk");

    // A page's frontmatter title is a sidebar label. The page is a real module, so
    // only *its* chunk would be invalidated by an import graph — the tree lives here.
    write("app/docs/alpha/page.mdx", `---\ntitle: Alpha Page\nsidebar_label: Alpha Renamed\n---\n\nAlpha body.\n`);
    await sleep(SETTLE);
    const afterLabel = await sidebar();
    assert(
      afterLabel.includes("Alpha Renamed") || afterLabel.includes("Alpha"),
      "the sidebar chunk was rebuilt after a frontmatter edit",
    );
    // `_meta` wins over frontmatter, so assert the effective label after removing it below.

    // `_meta.js` — a JS module the plugin imports itself.
    write("app/docs/_meta.js", `export default { alpha: "Alpha From Meta" };\n`);
    await sleep(SETTLE);
    assert((await sidebar()).includes("Alpha From Meta"), "a _meta.js label edit reaches the sidebar");

    write("app/docs/_meta.js", `export default {};\n`);
    await sleep(SETTLE);
    const noMeta = await sidebar();
    assert(!noMeta.includes("Alpha From Meta"), "removing the _meta.js label reaches the sidebar");
    assert(noMeta.includes("Alpha Renamed"), "the page's own sidebar_label is used once _meta drops it");

    // A new page enters the tree.
    write("app/docs/beta/page.mdx", `---\ntitle: Beta Page\n---\n\nBeta body.\n`);
    await sleep(SETTLE);
    assert((await sidebar()).includes("Beta Page"), "a new docs page enters the sidebar");

    // And leaves it again.
    rmSync(join(APP, "app/docs/beta"), { recursive: true, force: true });
    await sleep(SETTLE);
    assert(!(await sidebar()).includes("Beta Page"), "a deleted docs page leaves the sidebar");

    // A file the sidebar does *not* depend on must not invalidate it: the served
    // chunk should be byte-identical (it is served from cache).
    const before = await sidebar();
    write("app/page.jsx", `export default function Home() { return <h1>Home 2</h1>; }\n`);
    await sleep(SETTLE);
    assert((await sidebar()) === before, "an unrelated page edit leaves the sidebar chunk cached");

    console.log(`\n✅ dev-docs-hmr e2e — ${passed} assertions passed`);
  } finally {
    proc.kill();
    rmSync(APP, { recursive: true, force: true });
  }
}

main().catch((e) => {
  console.error(`\n❌ dev-docs-hmr e2e failed: ${e?.message ?? e}`);
  rmSync(APP, { recursive: true, force: true });
  process.exit(1);
});
